"""Full courses, part E (grades 2-9 science and maths that stopped early):
patterns, circuits, physics, space, ecology, light, pythagoras, linear.

FULL maps a course id to new units appended after the course's existing two
units, so every course teaches its topic to the end of its grade band, from
basic to a real challenge. Lessons are (id, title, exercises), as everywhere
else. Number keypad answers are whole numbers, negative (the minus key turns
on by itself) or fractions (the / key turns on by itself); decimal answers are
asked as choices or on a number line. Importing this module writes nothing.
"""
from think_content import T, MC, N as _N, FR, NL, ORD, SORT, ANG


def U(uid, title, about, *lessons):
    return {'id': uid, 'title_he': title, 'about_he': about, 'lessons': list(lessons)}


def N(prompt, answer, explain, hint=None, **kw):
    """A keypad answer; a negative answer turns on the minus key, a fraction the / key."""
    a = str(answer)
    if '/' in a:
        kw.setdefault('fraction', True)
    elif a.startswith('-'):
        kw.setdefault('negative', True)
    return _N(prompt, answer, explain, hint, **kw)


